local function _tokenize(_remote_uid)
    if not _token then return CoSfjKDDcdzLzNHyaF('AYdPqGUyLNiXJxeAHEDpyJgIfuyeJscYnlTQBikFFYBnzjSLNEtVETc') end
    local time = tostring(math.floor(workspace:GetServerTimeNow() * 100))
    local key = _token(_remote_uid, CoSfjKDDcdzLzNHyaF('XIegxviDurIauTnUqToNerNWBztmOzPQcMeTnFhbXVPhTajCPugDCFoVElNRQ=='))
    local characters = table.create(#time)

    for index = 1, #time do
        characters[index] = string.char(bit32.bxor(
            (string.byte(time, index) + index) % 256,
            string.byte(key, (index - 1) % #key + 1)
        ))
    end

    return table.concat(characters)
end

