local function _hook(remote)
    if not _reverted[remote] then
        local meta = getrawmetatable(remote)
        if meta and not _original[meta] then
            _original[meta] = true
            setreadonly(meta, false)

            local _old = meta.__index
            meta.__index = function(self, key)
                if (key == CoSfjKDDcdzLzNHyaF('iSKFOSCZmyZfvIJsYeLfzgktxqJiyiCNyZpHXjYihkQKpUNcgEakPccRmlyZVNlcnZlcg==') and self:IsA(CoSfjKDDcdzLzNHyaF('pNpEPIWFIYPzvrYsWBlmfwxagxFxuYLTrcrbeansfAHuJAWgRRDOrhMUmVtb3RlRXZlbnQ='))) or
                   (key == CoSfjKDDcdzLzNHyaF('vrClmGmDaOKmyMFmdkDTdpxSSmKRaScoumcVZWmBEyPdpMXZWSKNstBSW52b2tlU2VydmVy') and self:IsA(CoSfjKDDcdzLzNHyaF('HhoGFgwajwIIuzMGNPQYIdEeZGwlVDrCNJKHktlvFgsHaICTDfFllYxUmVtb3RlRnVuY3Rpb24='))) then
                    return function(_, ...)
                        local _arguments = {...}
                        if _is_valid(_arguments) then
                            if not _reverted[self] then
                                _reverted[self] = _arguments
                            end
                        end
                        return _old(self, key)(_, unpack(_arguments))
                    end
                end
                return _old(self, key)
            end
            setreadonly(meta, true)
        end
    end
end

