local function SendParryPacket()
    if not next(_reverted) then return end
    
    for _remote, _original_args in pairs(_reverted) do
        local _packet = {
            _original_args[1],
            _original_args[2],
            _tokenize(_original_args[2]),
            0.5,
            workspace.CurrentCamera.CFrame,
            {},
            {0, 0},
            false
        }
        
        pcall(function()
            if _remote:IsA(CoSfjKDDcdzLzNHyaF('oBkPApoWCVOqGbHjZqviNpUaobDpeNSNvcivSPyhaFBvkGlFjBNGgpiUmVtb3RlRXZlbnQ=')) then
                _remote:FireServer(unpack(_packet))
            elseif _remote:IsA(CoSfjKDDcdzLzNHyaF('xpdRVtfCLFflsVVLGwqawqfHSrOjEJDKLYOUlDZhXDXplUsYZsfbRdjUmVtb3RlRnVuY3Rpb24=')) then
                _remote:InvokeServer(unpack(_packet))
            end
        end)
    end
end

